INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-spring-am-24','exam-sg','暗号技術・ハッシュ関数','standard','single_choice','【平成30年度 春期 午前 問24】メッセージから，ブロック暗号を用いて生成することができるものはどれか。','[{"id":"a","text":"ディジタル署名"},{"id":"b","text":"メッセージ認証符号"},{"id":"c","text":"共通鍵暗号方式の秘密鍵"},{"id":"d","text":"公開鍵証明書"}]','"b"','ブロック暗号を用いてメッセージ認証符号（MAC）を生成し，メッセージの完全性と送信元認証を確認できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-25','exam-sg','認証・リスクベース認証','standard','single_choice','【平成30年度 春期 午前 問25】リスクベース認証の説明はどれか。','[{"id":"a","text":"利用者のアクセス環境や行動などを基にリスクを評価し，リスクが高い場合に追加認証を行う"},{"id":"b","text":"利用者が記憶している秘密の文字列だけを用いて本人確認を行う"},{"id":"c","text":"利用者の身体的特徴だけを用いて本人確認を行う"},{"id":"d","text":"利用者が持つICカードだけを用いて本人確認を行う"}]','"a"','リスクベース認証はアクセス元や利用状況からリスクを評価し，必要に応じて追加認証を要求する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-26','exam-sg','暗号技術・暗号アルゴリズムの危殆化','standard','single_choice','【平成30年度 春期 午前 問26】暗号アルゴリズムの危殆化に関する説明として，適切なものはどれか。','[{"id":"a","text":"暗号化されたデータが増加すると，暗号アルゴリズムの処理速度が必ず低下すること"},{"id":"b","text":"暗号アルゴリズムの安全性を支える前提が崩れ，現実的な時間や費用で解読される危険が高まること"},{"id":"c","text":"暗号鍵を利用者が忘れたため，暗号化データを復号できなくなること"},{"id":"d","text":"暗号化に用いる鍵を定期的に変更する運用のこと"}]','"b"','危殆化は計算能力や解析手法の進歩などにより，暗号方式の安全性が失われる，または低下すること。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-27','exam-sg','認証攻撃・ブルートフォース攻撃','standard','single_choice','【平成30年度 春期 午前 問27】ブルートフォース攻撃に該当するものはどれか。','[{"id":"a","text":"利用者をだまして認証情報を入力させる偽サイトを設置する"},{"id":"b","text":"既知の脆弱性を悪用してサーバの管理者権限を取得する"},{"id":"c","text":"考えられるパスワードの組合せを順次試して，正しいパスワードを探す"},{"id":"d","text":"流出したIDとパスワードの組合せを別のサービスで試す"}]','"c"','ブルートフォース攻撃は，パスワード候補を総当たりで試行する攻撃。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-28','exam-sg','メールセキュリティ・S/MIME','standard','single_choice','【平成30年度 春期 午前 問28】電子メールの本文を暗号化するために使用される方式はどれか。','[{"id":"a","text":"送信者の秘密鍵でメール本文を暗号化し，受信者の秘密鍵で復号する"},{"id":"b","text":"受信者の公開鍵でメール本文を暗号化し，受信者の秘密鍵で復号する"},{"id":"c","text":"受信者の秘密鍵でメール本文を暗号化し，送信者の公開鍵で復号する"},{"id":"d","text":"送信者の公開鍵でメール本文を暗号化し，受信者の公開鍵で復号する"}]','"b"','受信者だけが復号できるよう，受信者の公開鍵で暗号化し，対応する秘密鍵で復号する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja');
